package cli

import (
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/spf13/cobra"

	"github.com/patrikmichi/zuano/internal/brand"
	"github.com/patrikmichi/zuano/internal/codegen"
	"github.com/patrikmichi/zuano/internal/textsafe"
)

// generatedMarker starts every generated file; a file without it is not overwritten.
const generatedMarker = "Generated by " + brand.Name + " generate"

// GenerateCmd returns `zuano generate`.
func GenerateCmd() *cobra.Command {
	var f approvalFlags
	var services, lang, outFile string
	var noTriggers, noTools, force bool
	cmd := &cobra.Command{
		Use:   "generate --services github,slack",
		Short: "Write TypeScript or Python types for trigger payloads and tool inputs",
		Long: `Reads the trigger catalog and the tool descriptions of the services you name
and writes one file that types them: TriggerPayloads maps each trigger type to
its event data, ToolInputs maps each tool to its arguments. With the typed
parse() of the SDK, parse<'github.push'>() narrows the event.

The language is found from the project (package.json or tsconfig.json for
TypeScript, pyproject.toml, requirements.txt or setup.py for Python); say
--lang when both or neither are there. A file this command did not write is
never overwritten without --force.`,
		Example: `  zuano generate --services github,slack
  zuano generate --services gmail --lang py --out src/zuano_gen.py`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			names := commaList(services)
			if len(names) == 0 {
				return errors.New("name the services with --services, such as --services github,slack")
			}
			for _, n := range names {
				if n == "" || strings.ContainsAny(n, "/?#% ") {
					return fmt.Errorf("%q is not a service", textsafe.Clean(n))
				}
			}
			language, err := generateLanguage(lang)
			if err != nil {
				return err
			}
			if outFile == "" {
				outFile = map[string]string{"ts": "zuano.gen.ts", "py": "zuano_gen.py"}[language]
			}
			if prev, err := os.ReadFile(outFile); err == nil && !force && !strings.Contains(string(prev[:min(len(prev), 200)]), generatedMarker) {
				return fmt.Errorf("%s exists and was not written by %s; choose another --out or pass --force", textsafe.Clean(outFile), brand.Name)
			}
			c, err := approvalsClient(f.gatewayURL)
			if err != nil {
				return err
			}
			in := codegen.Input{Header: generatedMarker + ". Do not edit."}
			ctx := cmd.Context()
			seen := map[string]bool{}
			if !noTriggers {
				for _, svc := range names {
					var doc struct {
						Types []triggerType `json:"types"`
					}
					if _, err := gatewayJSON(ctx, c, http.MethodGet, triggersAPI+"/trigger-types?service="+url.QueryEscape(svc), nil, &doc); err != nil {
						return err
					}
					for _, t := range doc.Types {
						if t.Output != nil && !seen[t.Slug] {
							seen[t.Slug] = true
							in.Triggers = append(in.Triggers, codegen.Named{Key: t.Slug, Schema: t.Output})
						}
					}
				}
			}
			if !noTools {
				var all IntegrationsResponse
				if _, err := gatewayJSON(ctx, c, http.MethodGet, "/api/integrations", nil, &all); err != nil {
					return err
				}
				want := map[string]bool{}
				for _, n := range names {
					want[n] = true
				}
				found := map[string]bool{}
				for _, svc := range all.Services {
					if !want[svc.ID] {
						continue
					}
					found[svc.ID] = true
					for _, t := range svc.Tools {
						if t.InputSchema != nil {
							in.Tools = append(in.Tools, codegen.Named{Key: svc.ID + "." + t.Name, Schema: t.InputSchema})
						}
					}
				}
				for _, n := range names {
					if !found[n] {
						fmt.Fprintf(cmd.ErrOrStderr(), "No tools found for %q; check the name with `%s`.\n", textsafe.Clean(n), brand.Cmd("services"))
					}
				}
			}
			if len(in.Triggers)+len(in.Tools) == 0 {
				return errors.New("the gateway described no triggers or tools for those services")
			}
			sort.Slice(in.Triggers, func(i, j int) bool { return in.Triggers[i].Key < in.Triggers[j].Key })
			sort.Slice(in.Tools, func(i, j int) bool { return in.Tools[i].Key < in.Tools[j].Key })
			var src string
			if language == "ts" {
				src = codegen.TypeScript(in)
			} else {
				src = codegen.Python(in)
			}
			if dir := filepath.Dir(outFile); dir != "." {
				if err := os.MkdirAll(dir, 0o755); err != nil {
					return err
				}
			}
			if err := os.WriteFile(outFile, []byte(src), 0o644); err != nil {
				return err
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Wrote %d trigger payload(s) and %d tool input(s) to %s\n", len(in.Triggers), len(in.Tools), outFile)
			return nil
		},
	}
	f.bind(cmd, "Unused: the command writes a source file")
	_ = cmd.Flags().MarkHidden("json")
	cmd.Flags().StringVar(&services, "services", "", "Comma-separated services, such as github,slack")
	cmd.Flags().StringVar(&lang, "lang", "", "ts or py (default: found from the project)")
	cmd.Flags().StringVar(&outFile, "out", "", "File to write (default zuano.gen.ts or zuano_gen.py)")
	cmd.Flags().BoolVar(&noTriggers, "no-triggers", false, "Leave out trigger payloads")
	cmd.Flags().BoolVar(&noTools, "no-tools", false, "Leave out tool inputs")
	cmd.Flags().BoolVar(&force, "force", false, "Overwrite a file this command did not write")
	return cmd
}

func generateLanguage(flag string) (string, error) {
	switch flag {
	case "ts", "typescript":
		return "ts", nil
	case "py", "python":
		return "py", nil
	case "":
	default:
		return "", fmt.Errorf("--lang must be ts or py")
	}
	exists := func(names ...string) bool {
		for _, n := range names {
			if _, err := os.Stat(n); err == nil {
				return true
			}
		}
		return false
	}
	ts := exists("package.json", "tsconfig.json")
	py := exists("pyproject.toml", "requirements.txt", "setup.py")
	switch {
	case ts && !py:
		return "ts", nil
	case py && !ts:
		return "py", nil
	}
	return "", errors.New("could not tell TypeScript from Python in this directory; pass --lang ts or --lang py")
}
